%------------------------------------------------------------
%   SVPWM Function  v1.0
%   Editor: Sheeper Xu
%   Data: 2023/11
%------------------------------------------------------------
function [Tcm,sector] = fcn(alpha, beta, Vdc, Ts)
%输出变量初始化
    tcm1=0;
    tcm2=0;
    tcm3=0;
%判断中间变量
    ref1=beta;
    ref2=-1/2*beta+sqrt(3)*alpha/2;
    ref3=-1/2*beta-sqrt(3)*alpha/2;
%扇区判断
    if(ref1>0)        
        a=1;
    else        
        a=0;
    end
    if(ref2>0)         
        b=1;
    else         
        b=0;
    end
    if(ref3>0)       
        c=1;
    else        
        c=0;
    end
    sector=4*c+2*b+a; %扇区选择数计算
%------------------------------------------------------------
    % 扇区-sector 映射
    %扇区      I  II  III  IV  V  VI
    % sector 3  1  5   4   6  12
%------------------------------------------------------------
%设置矢量作用时间中间量
    X=Ts*sqrt(3)/Vdc*beta;
    Y=Ts*sqrt(3)/Vdc*(sqrt(3)*alpha+beta)/2;
    Z=Ts*sqrt(3)/Vdc*(-sqrt(3)*alpha+beta)/2;
%------------------------------------------------------------
% sector-矢量作用时间中间量映射
    % sector   1    2    3    4   5    6  
    %    t1       Z   Y   -Z  -X   X   -Y
    %    t2       Y  -X    X   Z  -Y   -Z
    %    t0            Ts-t1-t2
%------------------------------------------------------------
% 矢量作用时间计算
 switch(sector)
        case 1
            t1=Z;            
            t2=Y;
        case 2
            t1=Y;           
            t2=-X;
        case 3
            t1=-Z;           
            t2=X;
        case 4
            t1=-X;       
            t2=Z;
        case 5
            t1=X;       
            t2=-Y;
     otherwise
            t1=-Y;       
            t2=-Z;
 end
%过调制处理
if((t1+t2)>Ts)
    t1=Ts*(t1/(t1+t2));
    t2=Ts*(t2/(t1+t2));
end
 t0=(Ts-t1-t2)/2; %零矢量作用时间

%开关切换时间计算(7段式）
    %设置中间变量ta,tb,tc
    ta=t0/2; 
    tb=ta+t1/2; 
    tc=tb+t2/2; 
    %设置a,b,c开关的切换时间分别为tcm1,tcm2,tmc3
%------------------------------------------------------------
    % sector-开关切换时间映射关系
    %   N     1   2   3   4   5   6
    % tcm1 tb  ta  ta  tc  tc  tb
    % tcm2 ta  tc  tb  tb  ta  tc
    % tcm3 tc  tb  tc  ta  tb  ta
%------------------------------------------------------------
switch(sector)
    case 1
        tcm1=tb;    tcm2=ta;    tcm3=tc;
    case 2
        tcm1=ta;    tcm2=tc;    tcm3=tb;
    case 3
        tcm1=ta;    tcm2=tb;    tcm3=tc;
    case 4
        tcm1=tc;    tcm2=tb;    tcm3=ta;
    case 5
        tcm1=tc;    tcm2=ta;    tcm3=tb;
    case 6
        tcm1=tb;    tcm2=tc;    tcm3=ta;
end 

Tcm=[tcm1,tcm2,tcm3]; %输出开关切换时间
